/**
 * MCP tools for project discovery and analysis.
 */
import { defineSchema, lazySchema } from "../../../src/schemas/index.js";
import { join } from "../../../src/platform/compat/path/index.js";
import { cwd } from "../../../src/platform/index.js";
import { withSpan } from "../../../src/observability/tracing/otlp-setup.js";
import { directoryExists, fileExists, getFs, getProjectDir, ROUTE_FILTER_MAP, scanDirectory, toComponentName, } from "./helpers.js";
// ============================================================================
// Tool: vf_list_routes
// ============================================================================
const getListRoutesInput = defineSchema((v) => v.object({
    type: v.enum(["all", "pages", "api", "layouts"]).optional().default("all").describe("Filter routes by type"),
    projectPath: v.string().optional().describe("Project directory (defaults to current working directory)"),
}));
const listRoutesInput = lazySchema(getListRoutesInput);
export const vfListRoutes = {
    name: "vf_list_routes",
    title: "List Routes",
    annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
    description: "Use this when you need to discover all routes in the project including pages, API routes, layouts, error, loading, and not-found routes. Returns an array of route info with path, type, and file. Do not use for rendering a route. Use vf_preview_route instead.",
    inputSchema: listRoutesInput,
    execute: (input) => withSpan("cli.mcp.tool.vf_list_routes", async () => {
        const projectDir = getProjectDir(input.projectPath);
        const appDir = join(projectDir, "app");
        const fs = getFs();
        const routes = [];
        if (await directoryExists(appDir)) {
            await scanDirectory(appDir, "", routes, fs);
        }
        if (input.type === "all")
            return routes;
        const allowedTypes = ROUTE_FILTER_MAP[input.type] ?? [];
        return routes.filter((route) => allowedTypes.includes(route.type));
    }, { "tool.filter_type": input.type }),
};
// ============================================================================
// Tool: vf_get_project_context
// ============================================================================
const getGetProjectContextInput = defineSchema((v) => v.object({
    projectPath: v.string().optional().describe("Project directory (defaults to current working directory)"),
}));
const getProjectContextInput = lazySchema(getGetProjectContextInput);
const STANDARD_DIRS = [
    "app",
    "pages",
    "components",
    "lib",
    "ai",
    "agents",
    "tools",
    "workflows",
    "tasks",
    "prompts",
    "resources",
    "skills",
    "integrations",
];
const AI_PRIMITIVE_DIRS = [
    "ai",
    "agents",
    "tools",
    "workflows",
    "tasks",
    "prompts",
    "resources",
    "skills",
];
const BUILTIN_AUTH_ROUTES = ["login", "logout", "me", "signup", "register"];
const FEATURE_PATTERNS = [
    ["lib/auth.ts", "auth"],
    ["lib/redis.ts", "redis"],
    ["workflows", "workflows"],
];
async function detectDirectories(projectDir) {
    const directories = {};
    for (const dir of STANDARD_DIRS) {
        if (await directoryExists(join(projectDir, dir))) {
            directories[dir] = dir;
        }
    }
    return directories;
}
async function detectIntegrations(projectDir, fs) {
    const authDir = join(projectDir, "app/api/auth");
    if (!await directoryExists(authDir))
        return [];
    const integrations = [];
    try {
        for await (const entry of fs.readDir(authDir)) {
            if (entry.isDirectory && !BUILTIN_AUTH_ROUTES.includes(entry.name)) {
                integrations.push(entry.name);
            }
        }
    }
    catch {
        // Ignore read errors
    }
    return integrations;
}
async function detectFeatures(projectDir, hasAI) {
    const features = [];
    if (hasAI)
        features.push("ai");
    for (const [path, feature] of FEATURE_PATTERNS) {
        if (await fileExists(join(projectDir, path))) {
            features.push(feature);
        }
    }
    return features;
}
async function hasAgUiRoute(projectDir) {
    return await fileExists(join(projectDir, "app/api/ag-ui/route.ts"));
}
async function hasAiPrimitiveDirectory(projectDir) {
    for (const dir of AI_PRIMITIVE_DIRS) {
        if (await directoryExists(join(projectDir, dir)))
            return true;
    }
    return false;
}
async function getProjectName(projectDir, fs) {
    try {
        const content = await fs.readTextFile(join(projectDir, "package.json"));
        const pkg = JSON.parse(content);
        if (pkg.name)
            return pkg.name;
    }
    catch {
        // Fall back to directory name
    }
    return projectDir.split("/").pop() || "project";
}
export const vfGetProjectContext = {
    name: "vf_get_project_context",
    title: "Project Context",
    annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
    description: "Use this when you need to understand the project structure, conventions, and capabilities at the start of a coding session. Also returns route information. Do not use for detailed per-route rendering. Use vf_preview_route instead.",
    inputSchema: getProjectContextInput,
    execute: (input) => withSpan("cli.mcp.tool.vf_get_project_context", async () => {
        const projectDir = getProjectDir(input.projectPath);
        const fs = getFs();
        const hasApp = await directoryExists(join(projectDir, "app"));
        const hasPages = await directoryExists(join(projectDir, "pages"));
        const router = hasApp ? "app" : hasPages ? "pages" : "app";
        const routes = [];
        if (hasApp) {
            await scanDirectory(join(projectDir, "app"), "", routes, fs);
        }
        const directories = await detectDirectories(projectDir);
        const hasAI = await hasAiPrimitiveDirectory(projectDir) || await hasAgUiRoute(projectDir);
        const integrations = await detectIntegrations(projectDir, fs);
        const features = await detectFeatures(projectDir, hasAI);
        const name = await getProjectName(projectDir, fs);
        return { name, router, routes, directories, hasAI, integrations, features };
    }, { "tool.projectDir": input.projectPath ?? "cwd" }),
};
// ============================================================================
// Tool: vf_get_component_tree
// ============================================================================
const getGetComponentTreeInput = defineSchema((v) => v.object({
    route: v.string().describe("Route path to analyze (e.g., '/', '/dashboard')"),
    projectPath: v.string().optional().describe("Project directory (defaults to current working directory)"),
}));
const getComponentTreeInput = lazySchema(getGetComponentTreeInput);
function buildRoutePaths(route) {
    const segments = route.split("/").filter(Boolean);
    const paths = [""];
    for (const segment of segments) {
        paths.push(paths[paths.length - 1] + "/" + segment);
    }
    return paths;
}
function toRelativePath(absolutePath, projectDir) {
    return absolutePath.replace(projectDir + "/", "");
}
export const vfGetComponentTree = {
    name: "vf_get_component_tree",
    title: "Component Tree",
    annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
    description: "Use this when you need to analyze the component hierarchy for a specific route including layouts, providers, and nested components. Returns the component tree structure. Do not use for listing all routes. Use vf_list_routes instead.",
    inputSchema: getComponentTreeInput,
    execute: (input) => withSpan("cli.mcp.tool.vf_get_component_tree", async () => {
        const projectDir = getProjectDir(input.projectPath);
        const fs = getFs();
        const tree = [];
        const layouts = [];
        const providers = [];
        for (const routePath of buildRoutePaths(input.route)) {
            const layoutPath = join(projectDir, "app", routePath, "layout.tsx");
            if (!await fileExists(layoutPath))
                continue;
            const relativePath = toRelativePath(layoutPath, projectDir);
            layouts.push(relativePath);
            tree.push({
                name: toComponentName(routePath || "Root") + "Layout",
                type: "layout",
                file: relativePath,
            });
        }
        const pagePath = join(projectDir, "app", input.route, "page.tsx");
        if (await fileExists(pagePath)) {
            tree.push({
                name: toComponentName(input.route || "Home") + "Page",
                type: "page",
                file: toRelativePath(pagePath, projectDir),
            });
        }
        const providersDir = join(projectDir, "providers");
        if (await directoryExists(providersDir)) {
            try {
                for await (const entry of fs.readDir(providersDir)) {
                    if (!entry.isFile)
                        continue;
                    if (!entry.name.endsWith(".tsx") && !entry.name.endsWith(".mdx"))
                        continue;
                    providers.push(`providers/${entry.name}`);
                }
            }
            catch {
                // No providers
            }
        }
        return { route: input.route, tree, layouts, providers };
    }, { "tool.route": input.route }),
};
// ============================================================================
// Tool: vf_list_local_projects
// ============================================================================
const getListLocalProjectsInput = defineSchema((v) => v.object({
    directory: v.string().optional().describe("Directory to scan for projects (defaults to current directory and common locations)"),
    depth: v.number().optional().default(2).describe("How deep to scan (1 = immediate children, 2 = grandchildren)"),
}));
const listLocalProjectsInput = lazySchema(getListLocalProjectsInput);
async function detectVeryfrontProject(projectPath) {
    const fs = getFs();
    const configExists = await fileExists(join(projectPath, "veryfront.config.ts")) ||
        await fileExists(join(projectPath, "veryfront.config.js"));
    if (!configExists && !await fileExists(join(projectPath, "veryfront.json")))
        return null;
    let name = projectPath.split("/").pop() || "unknown";
    try {
        const pkgContent = await fs.readTextFile(join(projectPath, "package.json"));
        const pkg = JSON.parse(pkgContent);
        if (pkg.name)
            name = pkg.name;
    }
    catch {
        // Use directory name
    }
    const hasAppDir = await directoryExists(join(projectPath, "app"));
    const hasAIDir = await directoryExists(join(projectPath, "ai"));
    const hasAgentRoute = await hasAgUiRoute(projectPath);
    let template;
    if (hasAIDir || hasAgentRoute)
        template = "ai-agent";
    else if (hasAppDir)
        template = "minimal";
    const integrations = [];
    const authDir = join(projectPath, "app/api/auth");
    if (await directoryExists(authDir)) {
        try {
            for await (const entry of fs.readDir(authDir)) {
                if (!entry.isDirectory)
                    continue;
                if (["login", "logout", "me", "signup", "register", "callback"].includes(entry.name)) {
                    continue;
                }
                integrations.push(entry.name);
            }
        }
        catch {
            // Ignore
        }
    }
    return {
        name,
        path: projectPath,
        template,
        hasAI: hasAIDir || hasAgentRoute,
        integrations,
    };
}
async function scanForProjects(baseDir, depth, projects) {
    const fs = getFs();
    const project = await detectVeryfrontProject(baseDir);
    if (project) {
        projects.push(project);
        return;
    }
    if (depth <= 0)
        return;
    try {
        for await (const entry of fs.readDir(baseDir)) {
            if (!entry.isDirectory)
                continue;
            if (entry.name.startsWith(".") || entry.name === "node_modules")
                continue;
            await scanForProjects(join(baseDir, entry.name), depth - 1, projects);
        }
    }
    catch {
        // Permission error or not a directory
    }
}
export const vfListLocalProjects = {
    name: "vf_list_local_projects",
    title: "List Local Projects",
    annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
    description: "Use this when you need to discover Veryfront projects on the local filesystem by scanning for veryfront.config.ts files. Returns project info including template type and integrations. Do not use for project structure details. Use vf_get_project_context instead.",
    inputSchema: listLocalProjectsInput,
    execute: (input) => withSpan("cli.mcp.tool.vf_list_local_projects", async () => {
        const projects = [];
        await scanForProjects(input.directory ?? cwd(), input.depth, projects);
        return projects.sort((a, b) => a.name.localeCompare(b.name));
    }, { "tool.depth": input.depth }),
};
